<?php

namespace App\Models;

use App\Enums\ApprovalStepStatus;
use App\Enums\ApprovalStepType;
use Illuminate\Database\Eloquent\Attributes\Fillable;
use Illuminate\Database\Eloquent\Factories\HasFactory;
use Illuminate\Database\Eloquent\Model;
use Illuminate\Database\Eloquent\Relations\BelongsTo;
use Illuminate\Database\Eloquent\Relations\HasMany;

/*
 * Approval chains are generated by Laravel.
 *
 * No fields are mass assignable because the browser must not choose the
 * approver, level, status, comment, or decision timestamp directly.
 */
#[Fillable([])]
class RequestApprovalStep extends Model
{
    use HasFactory;

    /**
     * Convert stored values into useful PHP types.
     *
     * @return array<string, string>
     */
    protected function casts(): array
    {
        return [
            'level' => 'integer',
            'step_type' => ApprovalStepType::class,
            'status' => ApprovalStepStatus::class,
            'acted_at' => 'datetime',
        ];
    }

    /**
     * The request that owns this approval step.
     */
    public function requestForm(): BelongsTo
    {
        return $this->belongsTo(RequestForm::class);
    }

    /**
     * The user expected to act on this step.
     */
    public function approver(): BelongsTo
    {
        return $this->belongsTo(
            User::class,
            'approver_id'
        );
    }

    /**
     * Files uploaded by delegated approval staff with their approval.
     */
    public function attachments(): HasMany
    {
        return $this->hasMany(
            RequestApprovalAttachment::class,
            'request_approval_step_id',
        );
    }

    /**
     * Named for Laravel's scoped binding of {approvalAttachment}.
     */
    public function approvalAttachments(): HasMany
    {
        return $this->attachments();
    }
}
